(() => {
  const box = document.createElement('div');
  box.id = 'theorem-spike-box';
  box.style.cssText = 'position:fixed;left:40px;bottom:40px;width:120px;height:120px;border-radius:12px;z-index:99999;pointer-events:none';
  document.body.appendChild(box);
  const started = performance.now();
  window.theoremSpike = { callbacks: 0, done: false };
  const tick = (now) => {
    const t = (now - started) / 1000;
    window.theoremSpike.callbacks += 1;
    box.style.transform = `translateX(${Math.round(300 + 280 * Math.sin(t * 2))}px) rotate(${Math.round(t * 90)}deg)`;
    box.style.background = `hsl(${Math.round(t * 72) % 360} 70% 55%)`;
    if (t < 6) requestAnimationFrame(tick); else window.theoremSpike.done = true;
  };
  requestAnimationFrame(tick);
  return 'started';
})()
